Here is the commit message:
network: fix invalid memory access

This fixes a bug introduced by 959f65d32ec15cf84afe3efff1a18b0987b56c60.

Here is the root cause:
The bug was caused by improper memory management where networks were not being freed correctly in the `manager_free` function, leading to potential invalid memory access when the manager was deallocated. This could result in dangling pointers if the networks were still referenced after being freed. Additionally, the `link_free` function did not properly handle the removal of links from bond networks, which could also lead to invalid memory access if a link was freed while still being referenced in a bond's list of slaves.

Here is the patch:

 void manager_free(Manager *m) {
         AddressPool *pool;
         Network *network;
         Link *link;

         if (!m)
                 return;

         free(m->state_file);

         sd_netlink_unref(m->rtnl);
         sd_netlink_unref(m->genl);
         sd_resolve_unref(m->resolve);

-        while ((network = m->networks))
-                network_free(network);
-
         while ((link = hashmap_first(m->dhcp6_prefixes)))
                 manager_dhcp6_prefix_remove_all(m, link);
         hashmap_free(m->dhcp6_prefixes);

         while ((link = hashmap_steal_first(m->links))) {
                 if (link->dhcp6_client)
                         (void) dhcp6_lease_pd_prefix_lost(link->dhcp6_client, link);
                 link_unref(link);
         }

         m->dirty_links = set_free_with_destructor(m->dirty_links, link_unref);
         m->links = hashmap_free(m->links);
         m->links_requesting_uuid = set_free(m->links_requesting_uuid);
         set_free(m->duids_requesting_uuid);

+        while ((network = m->networks))
+                network_free(network);
+
         hashmap_free(m->networks_by_name);

         m->netdevs = hashmap_free_with_destructor(m->netdevs, netdev_unref);

         while ((pool = m->address_pools))
                 address_pool_free(pool);

         /* routing_policy_rule_free() access m->rules and m->rules_foreign.
          * So, it is necessary to set NULL after the sets are freed. */
         m->rules = set_free_with_destructor(m->rules, routing_policy_rule_free);
         m->rules_foreign = set_free_with_destructor(m->rules_foreign, routing_policy_rule_free);
         set_free_with_destructor(m->rules_saved, routing_policy_rule_free);

         sd_event_unref(m->event);

         sd_device_monitor_unref(m->device_monitor);

         sd_bus_flush_close_unref(m->bus);

         free(m->dynamic_timezone);
         free(m->dynamic_hostname);

         free(m);
 }



